function renderHome(){let s=state(),all=m.courses(s),allLeaves=m.resources(s).flatMap(r=>m.leaves(s,r.id)),overview=m.stats(s,allLeaves),thisWeek=m.weekStats(s,curWeek());$('#homeFocus').innerHTML=`<div class="home-focus-copy"><div class="focus-kicker">GENEL DURUM</div><h2>${overview.total?`${overview.done} konuyu tamamladın`:'Öğrenme yolculuğunu planla'}</h2><p>${overview.total?`${overview.total-overview.done} takip konusu kaldı.`:'Bir ders ve kaynak ekleyerek başlayabilirsin.'}</p></div><div class="focus-ring-wrap"><div class="focus-ring" style="--progress:${overview.pct}%"><div><strong>${overview.pct}%</strong><small>Toplam</small></div></div></div>`;let future=m.weeks(s.settings.start,s.settings.end).filter(w=>w>=curWeek()).slice(0,4);let upcoming=future.includes(curWeek())?future:[curWeek(),...future].slice(0,4);$('#homeWeeklyProgress').innerHTML=`<div class="section-head-row"><h3 class="section-title">Haftalık hedefler</h3><button class="text-link" data-page="weekly">Daha fazla</button></div><div class="home-week-progress-grid">${upcoming.map((w,i)=>{let st=m.weekStats(s,w);return `<button class="home-week-progress-card ${w===curWeek()?'current':'later'}" data-open-week="${w}"><div class="home-week-card-top"><strong>${w===curWeek()?'Bu hafta':'Sonraki hafta'}</strong><small>${range(w)}</small></div><div class="home-week-card-foot">${st.done}/${st.total} konu</div><div class="home-week-ring" style="--progress:${st.pct}%"><b>${st.pct}%</b></div></button>`}).join('')}</div>`;$('#homeCourseProgress').innerHTML=all.map(x=>{let st=m.courseStats(s,x.id);return `<div class="home-course-block"><div class="home-course-head"><strong>${esc(x.name)}</strong><span>${st.done}/${st.total} · ${st.pct}%</span></div>${m.resources(s,x.id).map(r=>{let t=m.resourceStats(s,r.id);return `<div class="home-source-row"><span class="home-source-name">${esc(r.title)}</span><span class="bar"><span style="width:${t.pct}%"></span></span><span class="home-source-count">${t.pct}%</span></div>`}).join('')}</div>`}).join('')||'<div class="home-empty-hint">Henüz ders eklenmemiş.</div>';$('#homeWeekTasks').innerHTML=m.assignmentRows(s,curWeek()).map(a=>`<div class="task-card"><div class="task-copy"><strong>${esc(a.node.title)}</strong><small>${esc(a.course.name)} · ${esc(a.resource.title)}</small></div><span class="tag ${m.status(s,a.nodeId)==='completed'?'good':''}">${m.status(s,a.nodeId)==='completed'?'Bitti':'Planlı'}</span></div>`).join('')||'<div class="empty-state">Henüz bu hafta için plan yok.</div>';renderReview()}
function renderReview(){let s=state(),r=m.activeReview(s);if(!r){$('#reviewContainer').innerHTML='';return}let arr=m.weeks(s.settings.start,s.settings.end).filter(w=>w>=curWeek());if(!arr.length)arr=[curWeek()];$('#reviewContainer').innerHTML=`<div class="section-card review-card"><div class="section-head-row"><h3 class="section-title">Geçen haftanın değerlendirmesi · ${range(r.weekStartDate)}</h3><span class="tag">${r.completedCount}/${r.plannedCount} · ${r.completionPercentage}%</span></div><p class="muted-text">Bitmemiş konular otomatik taşınmaz. İstersen seçerek yeni haftaya planlayabilirsin.</p><div class="review-options">${r.unfinishedNodeIds.map(nid=>{let n=node(nid);let res=n?resource(n.resourceId):null;return n?`<label><input type="checkbox" data-review-item="${nid}" checked> ${esc(n.title)} <span class="muted-text">${esc(courseName(res?.courseId))} / ${esc(res?.title||'')}</span></label>`:''}).join('')}</div><div class="week-actions"><select id="reviewTarget" class="small-select">${arr.map(w=>`<option value="${w}">${range(w)}</option>`).join('')}</select><button class="primary-btn" data-action="review-move" data-id="${r.id}">Seçilenleri taşı</button><button class="ghost-btn" data-action="review-unassign" data-id="${r.id}">Plansız bırak</button><button class="ghost-btn" data-action="review-defer" data-id="${r.id}">Sonra değerlendir</button></div></div>`}
function renderAnalytics(){let s=state(),cs=m.courses(s),rs=m.resources(s),nodes=rs.flatMap(r=>m.leaves(s,r.id)),st=m.stats(s,nodes),weekly=m.weekStats(s,curWeek()),planned=m.liveAssignments(s);$('#analyticsStats').innerHTML=[['Dersler',cs.length],['Kaynaklar',rs.length],['Tamamlanan konular',`${st.done}/${st.total}`],['Bu haftanın hedefi',`${weekly.pct}%`]].map(([k,v])=>`<div class="stat-card"><div class="stat-label">${k}</div><div class="stat-number">${v}</div></div>`).join('');$('#analyticsCourses').innerHTML=cs.map(x=>{let t=m.courseStats(s,x.id);return `<div class="analytics-course-block"><div class="analytics-course-title">${esc(x.name)} <small>${t.pct}%</small></div>${m.resources(s,x.id).map(r=>{let q=m.resourceStats(s,r.id);return `<div class="analytics-source-row"><span class="source-name">${esc(r.title)}</span><div class="bar"><span style="width:${q.pct}%"></span></div><span class="source-count">${q.done}/${q.total}</span></div>`}).join('')}</div>`}).join('')||'<div class="empty-state">Henüz kayıt yok.</div>';$('#analyticsPlan').innerHTML=`<div class="analytics-plan-metric"><span>Bu haftanın tamamlanma oranı</span><strong>${weekly.pct}%</strong></div><div class="analytics-plan-metric"><span>Planlanan (aktif)</span><strong>${planned.length}</strong></div><div class="analytics-plan-metric"><span>Bu hafta tamamlanmamış</span><strong>${Math.max(0,weekly.total-weekly.done)}</strong></div>`;let reviews=m.active(s,'reviews').sort((a,b)=>b.weekStartDate.localeCompare(a.weekStartDate));$('#completionChart').innerHTML=reviews.length?reviews.map(r=>`<div class="history-row"><span>${range(r.weekStartDate)}</span><div class="bar"><span style="width:${r.completionPercentage}%"></span></div><span>${r.completedCount}/${r.plannedCount}</span></div>`).join('')+'<p class="footer-note">Hafta bitiminde kaydedilmiş tarihsel sonuçlar sonradan değişmez.</p>':'<div class="history-empty">Geçmiş tamamlanmış hafta bulunmuyor. Geçmiş veriler oluşunca gerçek yüzdeler gösterilecek.</div>';$('#hoursBreakdown').innerHTML=renderStudy();
let snapshotWeeks=m.active(s,'reviews').sort((a,b)=>b.weekStartDate.localeCompare(a.weekStartDate)).slice(0,6).reverse().map(x=>x.weekStartDate);
$('#progressTimeline').innerHTML=snapshotWeeks.length?cs.map(co=>{let ress=m.resources(s,co.id);let items=ress.flatMap(r=>m.leaves(s,r.id));return `<div class="analytics-course-block"><strong>${esc(co.name)}</strong>${snapshotWeeks.map(w=>{let end=m.weekEndStamp(w),done=items.filter(n=>m.statusAt(s,n.id,end)==='completed').length;return `<div class="history-row"><span>${range(w)}</span><div class="bar"><span style="width:${percent(done,items.length)}%"></span></div><span>${percent(done,items.length)}%</span></div>`}).join('')}${ress.map(r=>{let ns=m.leaves(s,r.id);return `<div class="muted-text">${esc(r.title)}: ${snapshotWeeks.map(w=>`${labelDate(w)} %${percent(ns.filter(n=>m.statusAt(s,n.id,m.weekEndStamp(w))==='completed').length,ns.length)}`).join(' · ')}</div>`}).join('')}</div>`}).join(''):'<div class="history-empty">Gerçek ilerleme olayları biriktikçe kaynak ve ders geçmişi burada görüntülenecek.</div>'} 
// Productivity App summary is read-only. Never display unmapped subject labels.
function mappedStudy(){
 const totals=new Map(),mapping=state().mappings.filter(x=>!x.deletedAt&&x.courseId);
 for(const row of studyData?.subjects||[]){
  const match=mapping.find(x=>x.subject===row.subject),co=match&&course(match.courseId);
  if(!co)continue;
  const sec=Number(row.seconds);
  if(Number.isFinite(sec)&&sec>0)totals.set(co.id,(totals.get(co.id)||0)+sec);
 }
 return m.courses(state()).filter(co=>totals.has(co.id)).map(co=>({id:co.id,name:co.name,seconds:totals.get(co.id)})).sort((a,b)=>b.seconds-a.seconds);
}
function formatStudyTime(seconds){const mins=Math.floor(Math.max(0,seconds)/60);return mins>=60?`${Math.floor(mins/60)} sa ${String(mins%60).padStart(2,'0')} dk`:`${mins} dk`}
function studyStatus(){return studyLoading?'Çalışma süreleri yenileniyor…':studyError?'Çalışma verileri alınamadı. Yeniden dene.':studyLoadedAt?'Kaydedilmiş çalışma oturumları · Son kontrol '+new Date(studyLoadedAt).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'}):'Productivity App verileri yükleniyor…'}
function studySummaryCard(){
 const rows=mappedStudy(),total=rows.reduce((sum,row)=>sum+row.seconds,0),max=Math.max(1,...rows.map(r=>r.seconds));
 const content=rows.length?`<div class="lt-study-total"><span>Toplam eşleşen çalışma</span><strong>${formatStudyTime(total)}</strong><small>${rows.length} ders · yalnızca eşleşenler</small></div><div class="lt-study-bars">${rows.map(row=>`<div class="lt-study-line"><div><strong>${esc(row.name)}</strong><span>${formatStudyTime(row.seconds)}</span></div><div class="lt-study-track"><i style="width:${Math.max(2,100*row.seconds/max)}%"></i></div></div>`).join('')}</div>`:`<p class="muted-text lt-study-empty">${studyLoadedAt?'Henüz eşleşen ders için kayıtlı çalışma süresi yok. Ayarlar → Bağlantılar bölümünden oturum etiketlerini bir dersle eşleştir.':'Çalışma süreleri okunuyor…'}</p>`;
 return `<div class="section-head-row"><div><h3 class="section-title">Productivity App · Çalışma süresi</h3><p class="lt-study-sub">${esc(studyStatus())}</p></div><button class="tiny-btn" data-action="refresh-study" ${studyLoading?'disabled':''}>${studyLoading?'Yükleniyor…':'↻ Yenile'}</button></div><div class="lt-study-dashboard">${content}</div><p class="lt-study-foot">Çalışma süresi ilerleme yüzdesine katılmaz. Aktif oturumlar kaydedildikten sonra görünür.</p>`
}
function renderStudy(){return studySummaryCard()}
function renderStudyPanels(){
 const home=$('#homeStudyPanel');if(home)home.innerHTML=studySummaryCard();
 const co=$('#courseStudyPanel');if(co){let row=mappedStudy().find(r=>r.id===courseId);co.innerHTML=row?`<div class="lt-course-study-card"><span>◷ Productivity App · Kaydedilen çalışma</span><strong>${formatStudyTime(row.seconds)}</strong><small>${esc(studyStatus())}</small></div>`:''}
}
let studyLastAttempt=0;
function queueStudyRefresh(force=false){if(!c.account||studyLoading)return;if(!force&&Date.now()-studyLastAttempt<45000)return;studyLastAttempt=Date.now();void refreshStudy(false)}

function showSettingsTab(tab){
 settingsTab=['account','backup','integration','archive'].includes(tab)?tab:'account';
 $$('[data-settings-tab]').forEach(b=>{let active=b.dataset.settingsTab===settingsTab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});
 $$('[data-settings-panel]').forEach(x=>{x.hidden=x.dataset.settingsPanel!==settingsTab});
}
function filterHelp(raw){
 const query=(raw||'').trim().toLocaleLowerCase('tr-TR');let visible=0;
 $$('[data-help-section]').forEach(section=>{let matches=0;let header=section.querySelector('.help-section-header').textContent.toLocaleLowerCase('tr-TR');
 section.querySelectorAll('.help-question').forEach(item=>{const found=!query||header.includes(query)||item.textContent.toLocaleLowerCase('tr-TR').includes(query);item.hidden=!found;if(found)matches++});
 section.hidden=matches===0;if(matches)visible++});
 const empty=$('#helpEmpty');if(empty)empty.hidden=visible!==0;
}
function renderSettings(){if(!c.account)return;let backups=Object.keys(localStorage).filter(x=>x.startsWith('lt_conflict_backup_'+c.account.id+'_')).sort().reverse();$('#conflictBackups').innerHTML=backups.map(k=>`<div class="source-line"><div><strong>Yerel çakışma yedeği</strong><small>${esc(k.split('_').slice(-1)[0])}</small></div><button class="tiny-btn" data-action="download-conflict" data-id="${esc(k)}">İndir</button></div>`).join('')||'<div class="muted-text">Çakışma yedeği bulunmuyor.</div>';let archive=[...m.active(state(),'courses').filter(x=>x.archivedAt).map(x=>({id:x.id,label:x.name,kind:'Ders'})),...m.active(state(),'resources').filter(x=>x.archivedAt).map(x=>({id:x.id,label:x.title,kind:'Kaynak'}))];$('#archivedItems').innerHTML=archive.map(x=>`<div class="source-line"><div><strong>${esc(x.label)}</strong><small>${x.kind}</small></div><button class="tiny-btn" data-action="restore-archive" data-id="${x.id}">Geri yükle</button></div>`).join('')||'<div class="muted-text">Arşivde öğe yok.</div>';let summary=studyData?.subjects||[];$('#mappings').innerHTML=summary.map(t=>{let current=state().mappings.find(x=>x.subject===t.subject&&!x.deletedAt);return `<div class="mapping-row"><div><strong>${esc(t.subject)}</strong></div><span class="mapping-arrow">→</span><select data-map-subject="${esc(t.subject)}"><option value="">Eşleştirme yok</option>${m.courses(state()).map(x=>`<option value="${x.id}" ${current?.courseId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}).join('')||'<div class="empty-state">Önce çalışma sürelerini yenile.</div>'}
function openEditor(title,fields,callback){editorCallback=callback;$('#editorTitle').textContent=title;$('#editorFields').innerHTML=fields.map(f=>`<div class="field"><label for="edit-${f.key}">${esc(f.label)}</label>${f.type==='select'?`<select id="edit-${f.key}">${f.options.map(o=>`<option value="${esc(o.value)}" ${o.value===f.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea id="edit-${f.key}">${esc(f.value||'')}</textarea>`:`<input id="edit-${f.key}" ${f.type==='color'?'type="color"':f.type==='url'?'type="url"':'type="text"'} value="${esc(f.value||'')}">`}</div>`).join('');$('#editorDialog').showModal();$('#editorFields input,#editorFields select')?.focus()}
function textField(key,label,value=''){return {key,label,value}}
function optionField(key,label,value,options){return {key,label,value,type:'select',options}}
const courseChoices=()=>m.courses(state()).map(x=>({value:x.id,label:x.name}));
const resourceTypes=[{value:'book',label:'Kitap / ders kitabı'},{value:'video',label:'Video serisi / çevrim içi kurs'},{value:'website',label:'Web sitesi / çevrim içi materyal'},{value:'other',label:'Diğer'}];
function newCourse(){openEditor('Yeni ders',[textField('name','Ders adı'),optionField('category','Kategori','school',[{value:'school',label:'Okul'},{value:'independent',label:'Bağımsız'}]),{key:'color',label:'Ders rengi',type:'color',value:'#159e89'}],v=>{if(!v.name.trim())throw Error('Ders adı gerekli.');mutate(s=>{let r=m.add(s,'courses',{name:v.name.trim(),category:v.category,color:v.color,archivedAt:null});courseId=r.id;resourceId=null});go('courses')})}
function editCourse(){let x=course(courseId);if(!x)return;openEditor('Dersi düzenle',[textField('name','Ders adı',x.name),optionField('category','Kategori',x.category,[{value:'school',label:'Okul'},{value:'independent',label:'Bağımsız'}]),{key:'color',label:'Renk',type:'color',value:x.color}],v=>{if(!v.name.trim())throw Error('Ders adı boş olamaz.');mutate(s=>m.update(m.get(s,'courses',x.id),{name:v.name.trim(),category:v.category,color:v.color}))});}
function newResource(){if(!m.courses(state()).length){toast('Önce ders oluştur.');return newCourse()}openEditor('Yeni kaynak',[textField('title','Kaynak başlığı'),optionField('courseId','Ders',courseId||courseChoices()[0].value,courseChoices()),optionField('type','Tür','book',resourceTypes),{key:'sourceUrl',label:'Bağlantı (isteğe bağlı)',type:'url',value:''}],v=>{if(!v.title.trim())throw Error('Kaynak adı gerekli.');let newId;mutate(s=>{newId=m.add(s,'resources',{courseId:v.courseId,title:v.title.trim(),type:v.type,sourceUrl:v.sourceUrl.trim(),sourceAccess:'unavailable',importNotes:[],archivedAt:null}).id});courseId=v.courseId;resourceId=newId;go('courses');importStart(newId)})}
function editResource(id){let r=resource(id);if(!r)return;openEditor('Kaynağı düzenle',[textField('title','Başlık',r.title),optionField('courseId','Ders',r.courseId,courseChoices()),optionField('type','Tür',r.type,resourceTypes),{key:'sourceUrl',label:'Bağlantı',type:'url',value:r.sourceUrl}],v=>{if(!v.title.trim())throw Error('Başlık boş olamaz.');mutate(s=>m.update(m.get(s,'resources',id),{title:v.title.trim(),courseId:v.courseId,type:v.type,sourceUrl:v.sourceUrl.trim()}))})}
function addNode(parentId=null){let r=resource(resourceId);if(!r){toast('Önce bir kaynak seç.');return}openEditor(parentId?'Alt başlık ekle':'Bölüm / konu ekle',[textField('title','Başlık'),optionField('type','Tür','topic',[{value:'section',label:'Bölüm'},{value:'topic',label:'Konu'},{value:'quiz',label:'Alıştırma / quiz'},{value:'test',label:'Test'}])],v=>{if(!v.title.trim())throw Error('Başlık gerekli.');mutate(s=>{let siblings=m.children(s,parentId,r.id);m.add(s,'nodes',{resourceId:r.id,parentId,title:v.title.trim(),type:v.type,sortOrder:siblings.length})})})}
function editNode(id){let n=node(id);if(!n)return;let choices=[{value:'',label:'Kök başlık'},...m.nodes(state(),n.resourceId).filter(x=>x.id!==id&&!descendantIds(id).includes(x.id)).map(x=>({value:x.id,label:x.title}))];openEditor('Konuyu düzenle',[textField('title','Başlık',n.title),optionField('type','Tür',n.type,[{value:'section',label:'Bölüm'},{value:'topic',label:'Konu'},{value:'quiz',label:'Alıştırma'},{value:'test',label:'Test'}]),optionField('parent','Üst başlık',n.parentId||'',choices),textField('sort','Sıra',String(n.sortOrder))],v=>{if(!v.title.trim())throw Error('Başlık boş olamaz.');let order=Number(v.sort);if(!Number.isInteger(order)||order<0)throw Error('Sıra pozitif sayı olmalı.');mutate(s=>m.update(m.get(s,'nodes',id),{title:v.title.trim(),type:v.type,parentId:v.parent||null,sortOrder:order}))})}
function descendantIds(id){let s=state(),n=node(id);if(!n)return[];let ids=[];function walk(cur){for(const child of m.children(s,cur,n.resourceId)){ids.push(child.id);walk(child.id)}}walk(id);return ids}
function openNodeMenu(id){let n=node(id);if(!n)return;let st=m.status(state(),id);openEditor('Konu durumu',[optionField('status','Durum',st,[{value:'notstarted',label:'Başlanmadı'},{value:'progress',label:'Devam ediyor'},{value:'completed',label:'Bitti'}])],v=>mutate(s=>m.setStatus(s,id,v.status)))}
function moveTopic(id){let weeks=m.weeks(state().settings.start,state().settings.end);openEditor('Başka haftaya taşı',[optionField('week','Hedef hafta',selectedWeek,weeks.map(w=>({value:w,label:range(w)})))],v=>mutate(s=>m.assign(s,id,v.week)))}
function weeklySelect(){let s=state(),available=m.resources(s).flatMap(r=>m.leaves(s,r.id).map(n=>({n,r})));if(!available.length){toast('Önce kaynağına konu ekle.');return}let d=$('#editorDialog');$('#editorTitle').textContent='Haftaya konu ekle';$('#editorFields').innerHTML=`<div class="field"><label>Hedef hafta</label><select id="edit-week">${m.weeks(s.settings.start,s.settings.end).map(w=>`<option value="${w}" ${w===selectedWeek?'selected':''}>${range(w)}</option>`).join('')}</select></div><div class="item-picker">${available.map(({n,r})=>`<label><input type="checkbox" data-pick-node="${n.id}"><span>${esc(n.title)} <small>· ${esc(courseName(r.courseId))} / ${esc(r.title)}</small></span></label>`).join('')}</div>`;editorCallback=()=>{let ids=$$('[data-pick-node]:checked').map(x=>x.dataset.pickNode);if(!ids.length)throw Error('En az bir konu seç.');mutate(s=>ids.forEach(id=>m.assign(s,id,$('#edit-week').value)))};d.showModal()}
function importStart(id){let r=resource(id||resourceId);if(!r)return;importResourceId=r.id;pendingImport=null;const guide=imp.guidance(r);$('#importTitle').textContent=r.title+' · İçindekileri AI ile aktar';$('#aiPromptText').value=imp.prompt(r);$('#aiJson').value='';$('#importError').textContent='';$('#importCheckStatus').textContent='';$('#importGuide').innerHTML=`<h4>${esc(guide.title)}</h4><ol>${guide.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="import-guide-hint">${esc(guide.hint)}</p>`;$('#importStepPrompt').hidden=false;$('#importStepPreview').hidden=true;$('#importDialog').showModal()}
// Unified editor: all structural operations stay in one outline; existing record IDs remain stable.
function openOutline(id){const r=resource(id||resourceId);if(!r)return toast('Önce kaynak seç.');outlineResourceId=r.id;outlineFolded.clear();$('#outlineTitle').textContent=r.title+' · İçindekiler';renderOutline();$('#outlineDialog').showModal()}
function outlineOptions(rid,excludeId=null){const banned=new Set(excludeId?[excludeId,...descendantIds(excludeId)]:[]);return [{value:'',label:'En üst düzey'},...m.nodes(state(),rid).filter(n=>!banned.has(n.id)).map(n=>({value:n.id,label:n.title}))]}
function renderOutline(){
 const rid=outlineResourceId;if(!rid)return;
 const s=state(),items=m.nodes(s,rid),leaves=m.leaves(s,rid);
 const validIds=new Set(items.map(n=>n.id));for(const key of [...outlineFolded])if(!validIds.has(key))outlineFolded.delete(key);
 const typeName=n=>n.type==='quiz'?'Alıştırma':n.type==='test'?'Test':n.type==='section'?'Alt bölüm':'Konu';
 function branch(parent,depth,trail){if(depth>80)return '';
  return m.children(s,parent,rid).filter(n=>!trail.has(n.id)).map(n=>{
   const children=m.children(s,n.id,rid),hasKids=children.length>0,folded=outlineFolded.has(n.id);
   const label=depth===0?'Ünite':hasKids||n.type==='section'?'Alt başlık':typeName(n);
   return `<div class="outline-branch" role="treeitem" aria-level="${depth+1}" aria-label="${esc(n.title)}" ${hasKids?`aria-expanded="${!folded}"`:''}>
    <div class="outline-row outline-level-${Math.min(depth,3)} ${hasKids?'outline-parent':'outline-leaf'}">
     ${hasKids?`<button class="outline-toggle" data-outline="toggle" data-id="${n.id}" aria-label="${esc(n.title)} ${folded?'genişlet':'daralt'}" aria-expanded="${!folded}">${folded?'▸':'▾'}</button>`:'<span class="outline-toggle-spacer" aria-hidden="true"></span>'}
     <span class="outline-type" aria-hidden="true">${depth===0?'▣':hasKids||n.type==='section'?'▫':n.type==='quiz'?'◇':n.type==='test'?'⬡':'○'}</span>
     <div class="outline-name"><strong>${esc(n.title)}</strong><small>${label}${hasKids?' · '+children.length+' alt öğe':''}</small></div>
     <button class="outline-more" data-outline="menu" data-id="${n.id}" aria-label="${esc(n.title)} işlemleri" aria-haspopup="true">•••</button>
    </div>
    ${hasKids&&!folded?`<div class="outline-children" role="group">${branch(n.id,depth+1,new Set([...trail,n.id]))}</div>`:''}
   </div>`}).join('');}
 $('#outlineCount').textContent=items.length+' başlık · '+leaves.length+' takip konusu';
 $('#outlineTree').innerHTML=branch(null,0,new Set())||'<p class="muted-text">Henüz başlık yok. Üst bölüm ekleyebilir veya AI ile kaynak içindekilerini aktarabilirsin.</p>';
}
function outlineNodeEditor(id=null,parentId=null){const r=resource(outlineResourceId),n=id?node(id):null;if(!r)return;const parent=n?n.parentId:parentId,opts=outlineOptions(r.id,id);const fields=[textField('title','Başlık',n?.title||''),optionField('type','İçerik türü',n?.type||'section',[{value:'section',label:'Bölüm / alt bölüm'},{value:'topic',label:'Konu'},{value:'quiz',label:'Alıştırma / quiz'},{value:'test',label:'Test'}]),optionField('parentId','Hangi başlığın altında?',parent||'',opts)];$('#outlineDialog').close();openEditor(n?'Başlığı düzenle':'Yeni başlık ekle',fields,v=>{if(!v.title.trim())throw Error('Başlık boş olamaz.');let destination=v.parentId||null;let children=id?descendantIds(id):[];if(id&&(destination===id||children.includes(destination)))throw Error('Bir bölüm kendi altına taşınamaz.');mutate(s=>{if(n){let live=m.get(s,'nodes',id);const moving=live.parentId!==destination;const newOrder=m.children(s,destination,r.id).filter(x=>x.id!==id).length;m.update(live,{title:v.title.trim(),type:v.type,parentId:destination,sortOrder:moving?newOrder:live.sortOrder})}else m.add(s,'nodes',{resourceId:r.id,parentId:destination,title:v.title.trim(),type:v.type,sortOrder:m.children(s,destination,r.id).length})});outlineResourceId=r.id;renderOutline()});outlineReturnPending=true}
function outlineAction(action,id){const rid=outlineResourceId;if(!rid)return;const n=id?node(id):null;if(action==='toggle'){outlineFolded.has(id)?outlineFolded.delete(id):outlineFolded.add(id);return renderOutline()}if(action==='menu'){const n=node(id);if(!n)return;const anchor=document.querySelector(`[data-outline="menu"][data-id="${id}"]`);let menu=$('#outlineContextMenu');if(!menu){menu=document.createElement('div');menu.id='outlineContextMenu';menu.className='outline-context-menu';menu.setAttribute('role','menu');document.body.appendChild(menu)}if(menu.dataset.nodeId===id&&!menu.hidden){menu.hidden=true;return}menu.dataset.nodeId=id;menu.innerHTML=`<button data-outline="edit" data-id="${id}">✎ Düzenle / başka başlık altına taşı</button><button data-outline="add-child" data-id="${id}">＋ Alt başlık veya konu ekle</button><button data-outline="up" data-id="${id}">↑ Yukarı taşı</button><button data-outline="down" data-id="${id}">↓ Aşağı taşı</button><button class="outline-danger" data-outline="delete" data-id="${id}">Sil</button>`;menu.hidden=false;const bounds=anchor.getBoundingClientRect();menu.style.top=Math.min(bounds.bottom+5,innerHeight-230)+'px';menu.style.left=Math.max(8,Math.min(bounds.right-210,innerWidth-226))+'px';return}if(action==='add-root')return outlineNodeEditor();if(action==='add-child')return outlineNodeEditor(null,id);if(action==='edit')return outlineNodeEditor(id);if(action==='import'){ $('#outlineDialog').close(); return importStart(rid) }if(!n)return;$('#outlineContextMenu')?.setAttribute('hidden','');if(action==='delete'){let ids=[id,...descendantIds(id)],completed=ids.filter(x=>m.status(state(),x)!=='notstarted').length,assigned=ids.filter(x=>m.liveAssignments(state()).some(a=>a.nodeId===x)).length;let msg=`“${n.title}” ve ${ids.length-1} alt başlığı silinsin mi? ${completed} ilerleme kaydı, ${assigned} aktif plan etkilenebilir. İşlem geri alınamaz; önce JSON yedeği indir.`;if(!confirm(msg))return;mutate(s=>{for(let nid of ids){let item=m.get(s,'nodes',nid);if(item)m.remove(s,'nodes',item);m.unassign(s,nid)}});return renderOutline()}if(action==='up'||action==='down'){let sib=m.children(state(),n.parentId,rid),ix=sib.findIndex(x=>x.id===id),swap=sib[ix+(action==='up'?-1:1)];if(!swap)return;mutate(s=>{let a=m.get(s,'nodes',id),b=m.get(s,'nodes',swap.id),order=a.sortOrder;m.update(a,{sortOrder:b.sortOrder});m.update(b,{sortOrder:order})});renderOutline()}}
function previewRender(){if(!pendingImport)return;$('#previewInfo').textContent=`Kaynağa erişim: ${pendingImport.source_access==='full'?'Tam':pendingImport.source_access==='partial'?'Kısmi':'Erişilemedi'} · ${pendingImport.notes.length?pendingImport.notes.join(' · '):'Başlıkların kaynakla eşleştiğini kontrol et.'} · Sıralama ve üst başlıkları içe aktarmadan önce denetle.`;
  const flattened=[];function paths(nodes,prefix='',depth=0){nodes.forEach((n,i)=>{n.__path=prefix+String(i);flattened.push({path:n.__path,title:n.title,depth});paths(n.children,n.__path+'.',depth+1)})}paths(pendingImport.structure);
  function branch(nodes){return nodes.map(n=>{const parentPath=n.__path.includes('.')?n.__path.slice(0,n.__path.lastIndexOf('.')):'';let options='<option value="">Üst düzey</option>'+flattened.filter(x=>x.path!==n.__path&&!x.path.startsWith(n.__path+'.')).map(x=>`<option value="${esc(x.path)}" ${parentPath===x.path?'selected':''}>${'— '.repeat(Math.min(x.depth,8))}${esc(x.title)}</option>`).join('');return `<div class="tree-branch"><div class="tree-entry"><input data-tree-title="${n.__path}" value="${esc(n.title)}" aria-label="Başlık"><button class="tiny-btn" data-tree="add" data-path="${n.__path}" title="Alt başlık ekle">＋</button><button class="tiny-btn" data-tree="up" data-path="${n.__path}" title="Yukarı">↑</button><button class="tiny-btn" data-tree="down" data-path="${n.__path}" title="Aşağı">↓</button><button class="tiny-btn" data-tree="delete" data-path="${n.__path}">Sil</button></div><label class="tree-parent-label">Hangi başlığın altında?<select data-tree-parent="${n.__path}" aria-label="${esc(n.title)} üst başlık">${options}</select></label>${branch(n.children)}</div>`}).join('')}
  $('#importTree').innerHTML=branch(pendingImport.structure)||'<p class="muted-text">Boş kaynak haritası.</p>'}
function previewReparent(path,target){if(!pendingImport)return;const origin=pathLocation(path);if(target&&(target===path||target.startsWith(path+'.')))throw Error('Bir başlık kendi altına taşınamaz.');const dest=target?pathLocation(target).node:null;const moving=origin.node;origin.list.splice(origin.index,1);(dest?dest.children:pendingImport.structure).push(moving);previewRender()}
function pathLocation(path){let parts=String(path).split('.').map(Number),arr=pendingImport.structure,parent=null;for(const i of parts){if(!arr[i])throw Error('Başlık bulunamadı.');parent=arr[i];if(i!==parts[parts.length-1]){}arr=parent.children}let index=parts.pop(),list=pendingImport.structure;for(let i of parts)list=list[i].children;return {list,index,node:list[index]}}
function treeAction(act,path){let {list,index,node}=pathLocation(path);if(act==='delete')list.splice(index,1);if(act==='add')node.children.push({title:'Yeni alt başlık',children:[]});if(act==='up'&&index>0)[list[index-1],list[index]]=[list[index],list[index-1]];if(act==='down'&&index<list.length-1)[list[index],list[index+1]]=[list[index+1],list[index]];previewRender()}
function reviewAction(act,id){let current=m.get(state(),'reviews',id);if(!current)return;let ids=$$('[data-review-item]:checked').map(x=>x.dataset.reviewItem);if(act==='review-move'&&!ids.length){toast('En az bir konu seç.');return}mutate(s=>{let r=m.get(s,'reviews',id);if(act==='review-move'){let w=$('#reviewTarget').value;for(const nid of ids)if(node(nid))m.assign(s,nid,w)}if(act==='review-unassign')for(const nid of ids)if(node(nid))m.unassign(s,nid);if(act!=='review-defer')m.update(r,{status:'handled',reviewedAt:m.now()});else m.update(r,{status:'deferred',reviewedAt:null})});toast(act==='review-defer'?'Değerlendirme ertelendi.':'Değerlendirme kaydedildi.')}
async function refreshStudy(manual=true){if(studyLoading||!c.account)return;studyLoading=true;studyLastAttempt=Date.now();studyError='';renderStudyPanels();try{const result=await c.studySummary();if(!result||!Array.isArray(result.subjects))throw Error('Çalışma özeti uygun biçimde alınamadı.');studyData=result;studyLoadedAt=Date.now();$('#integrationStatus').textContent='Kaydedilmiş çalışma oturumları okundu. Yalnızca eşleşen dersler görüntülenir.';if(manual)toast('Çalışma süreleri güncellendi.')}catch(e){studyError=e.message||'Bağlantı hatası';$('#integrationStatus').textContent='Çalışma süreleri alınamadı: '+studyError;if(manual)toast(studyError)}finally{studyLoading=false;render()}}
function exportBackup(){let data=JSON.stringify(state(),null,2),blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`learning-tracker-backup-${m.dayISO(new Date())}.json`;a.click();URL.revokeObjectURL(url)}
async function importBackup(file){if(!file)return;try{const data=JSON.parse(await file.text());m.validateState(data);if(!confirm('Geçerli verinin yerini yedekle değiştirmek istiyor musun? Önce mevcut verinin otomatik bir kopyası indirilecek.'))return;exportBackup();c.setStateFromBackup(data);render();toast('Yedek geri yüklendi; senkronizasyon bekleniyor.')}catch(e){toast('Yedek yüklenemedi: '+e.message)}finally{$('#importBackup').value=''}}
function handleAction(action,id){if(action==='download-conflict'){let raw=localStorage.getItem(id);if(!raw)return toast('Yedek bulunamadı.');let url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='learning-tracker-conflict-backup.json';a.click();URL.revokeObjectURL(url);return}if(action==='archive-course'){if(!courseId||!confirm('Ders arşivlensin mi? Kayıtlar korunacak.'))return;mutate(s=>m.update(m.get(s,'courses',courseId),{archivedAt:m.now()}));return}if(action==='delete-course'){if(!courseId||!confirm('Ders silinsin mi? İlgili kaynaklar görünmez; geçmiş kayıtlar korunur.'))return;mutate(s=>m.remove(s,'courses',m.get(s,'courses',courseId)));return}if(action==='archive-resource'){if(!confirm('Kaynak arşivlensin mi?'))return;mutate(s=>m.update(m.get(s,'resources',id),{archivedAt:m.now()}));return}if(action==='delete-resource'){if(!confirm('Kaynak silinsin mi? Konu ilerlemeleri geçmişte korunur, aktif görünümden çıkar.'))return;mutate(s=>m.remove(s,'resources',m.get(s,'resources',id)));return}if(action==='restore-archive'){mutate(s=>{let x=m.get(s,'courses',id)||m.get(s,'resources',id);if(x)m.update(x,{archivedAt:null})});toast('Arşivden geri yüklendi.');return}if(action==='delete-node'){let n=node(id);if(!n||!confirm('Seçilen konu ve alt başlıkları silmek istiyor musun?'))return;let ids=[id,...descendantIds(id)];mutate(s=>{for(const nid of ids){let item=m.get(s,'nodes',nid);if(item)m.remove(s,'nodes',item);m.unassign(s,nid)}});return}if(action==='outline-editor')return openOutline(id||resourceId);if(action==='show-archive'){settingsTab='archive';return go('settings')}if(action==='add-course')return newCourse();if(action==='edit-course')return editCourse();if(action==='add-resource')return newResource();if(action==='edit-resource')return editResource(id);if(action==='add-section')return openOutline(resourceId);if(action==='edit-node')return editNode(id);if(action==='add-child')return addNode(id);if(action==='import-resource')return importStart(id);if(action==='add-weekly-topic')return weeklySelect();if(action==='refresh-study')return refreshStudy();if(action==='set-inprogress')return mutate(s=>m.setStatus(s,id,'progress'));if(action==='move-topic')return moveTopic(id);if(action==='unassign')return mutate(s=>m.unassign(s,id));if(action==='bulk-complete'){let root=node(id);return mutate(s=>descendantLeaves(root).forEach(x=>m.setStatus(s,x.node.id,'completed')))}if(action.startsWith('review-'))return reviewAction(action,id)}
